// Audit-event producer. Wraps publishEvent with the `audit.platform_event`
// envelope expected by platform-backend's subscriber arm. The subscriber
// drops events with no userId, so callers should not invoke this from
// background pollers or non-request paths.
//
// Wire envelope (snake_case, per the shared control-plane contract):
//
//   {
//     event_id:         <uuid>,                      // generated by publishEvent
//     event_type:       "audit.platform_event",      // the bridge type — see below
//     entity_type:      "connector",
//     entity_id:        <resourceId>,
//     tenant_id:        <tenant uuid>,
//     event_version:    1,
//     occurred_at:      <iso>,
//     payload: {                                     // AuditPlatformEventPayload
//       tenantId, userId,
//       eventType:    "connector.created"            // the WORKSPACE-facing audit event
//                                                    // (separate from envelope.event_type)
//       resourceType: "connector",
//       resourceId,
//       action:       "created",
//       previousState, newState, occurredAt,
//     }
//   }
//
// Pub/Sub message attributes (set automatically by publishEvent):
//
//   eventType  = "audit.platform_event"   // ⚠ envelope type, NOT payload.eventType.
//                                          // platform-backend's subscriber filters on this
//                                          // to dispatch to the audit-bridge handler.
//   entityType = "connector"
//   entityId   = <resourceId>
//   tenantId   = <tenant uuid>
//
// Subscribers that want to fan out by *workspace* event_type (e.g. only
// `connector.disconnected`) must read it from the payload, not from the
// message attributes. Attribute filters apply per-subscription in GCP and
// are coarse — they identify "this is a bridge audit envelope", not the
// inner human-facing event.

import { publishEvent } from './publisher.js';

export interface PublishAuditEventInput {
  tenantId: string;
  userId: string;
  eventType: string; // e.g. 'connector.created', 'connector.disconnected'
  resourceId: string;
  newState?: Record<string, unknown>;
  previousState?: Record<string, unknown>;
}

export async function publishAuditEvent(payload: PublishAuditEventInput): Promise<void> {
  await publishEvent({
    entityType: 'connector',
    entityId: payload.resourceId,
    eventType: 'audit.platform_event',
    eventVersion: 1,
    tenantId: payload.tenantId,
    payload: {
      tenantId: payload.tenantId,
      userId: payload.userId,
      eventType: payload.eventType,
      resourceType: 'connector',
      resourceId: payload.resourceId,
      action: payload.eventType.split('.').slice(1).join('.'),
      previousState: payload.previousState ?? null,
      newState: payload.newState ?? null,
      occurredAt: new Date().toISOString(),
    },
  });
}
